template<class T, class A> class vector
{
  T* first;
  T* last;
  T* limit;
public:
  vector();
  ~vector();
};

class malloc_alloc {};
class cface {};
class vert {};
class material;
class entity;
class po;

class vector3d
{
  float x, y, z;
};

class collision_geometry
{
public:
  collision_geometry();
  virtual ~collision_geometry();
protected:
  entity* owner;
  bool valid;
};

class chunk_file
{
  char storage[256];
public:
  chunk_file();
  ~chunk_file();
  void open(const char* name);
  void close();
};

typedef vector<cface, malloc_alloc> cface_vect;
typedef vector<vert, malloc_alloc> vert_vect;
typedef vector<int, malloc_alloc> intvector;

class cg_mesh : public collision_geometry
{
public:
  cg_mesh(const char* cg_mesh_fname, bool allow_warnings);
  virtual ~cg_mesh();
  void read_from_file(chunk_file& fs, bool allow_warnings);
protected:
  vert_vect raw_verts;
  vert_vect verts;
  cface_vect cfaces;
  vector<material*, malloc_alloc> materials;
  float cface_xmin;
  intvector lookup_low;
  intvector lookup_high;
  vector3d pivot;
  unsigned int flags;
  int lookup_size;
  float radius;
};

cg_mesh::cg_mesh(const char * cg_mesh_fname, bool allow_warnings ) : collision_geometry()
{
  chunk_file fs;
  fs.open(cg_mesh_fname);

  read_from_file( fs, allow_warnings );

  fs.close();
}
